import { NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabase/admin';
import { verifyAdminRequest } from '@/lib/auth/adminAuth';
import { recordAuditLog } from '@/lib/firestore/auditLogs';

export interface TestAngpaoVoucher {
  id: string;
  code: string;
  link: string;
  amount: number;
  maxUses: number;
  usedCount: number;
  usedBy: string[];
  isUsed: boolean;
  isActive: boolean;
  createdAt: string;
}

/**
 * GET: List all test Angpao vouchers generated by admin
 */
export async function GET(req: Request) {
  try {
    const authResult = await verifyAdminRequest(req);
    if (!authResult.isAdmin) {
      return NextResponse.json({ error: authResult.error || 'Forbidden' }, { status: 403 });
    }

    const { data, error } = await supabaseAdmin
      .from('redeem_codes')
      .select('*')
      .eq('code_type', 'angpao_test')
      .order('created_at', { ascending: false })
      .limit(50);

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    const vouchers: TestAngpaoVoucher[] = (data || []).map((row) => {
      const usedBy = Array.isArray(row.used_by)
        ? row.used_by
        : typeof row.used_by === 'string'
        ? JSON.parse(row.used_by || '[]')
        : [];
      const usedCount = Number(row.used_count) || 0;
      const maxUses = Number(row.max_uses) || 1;

      return {
        id: row.id,
        code: row.code,
        link: `https://gift.truemoney.com/campaign/?v=${encodeURIComponent(row.code)}`,
        amount: Number(row.credits) || 0,
        maxUses,
        usedCount,
        usedBy,
        isUsed: usedCount >= maxUses,
        isActive: Boolean(row.is_active),
        createdAt: row.created_at || new Date().toISOString(),
      };
    });

    return NextResponse.json({
      ok: true,
      vouchers,
    });
  } catch (err: any) {
    console.error('Error in GET /api/admin/angpao/test-gen:', err);
    return NextResponse.json({ error: err.message || 'Internal server error' }, { status: 500 });
  }
}

/**
 * POST: Generate a new test TrueMoney Angpao voucher link
 */
export async function POST(req: Request) {
  try {
    const authResult = await verifyAdminRequest(req);
    if (!authResult.isAdmin) {
      return NextResponse.json({ error: authResult.error || 'Forbidden' }, { status: 403 });
    }

    const body = await req.json().catch(() => ({}));
    const rawAmount = Number(body.amount);
    const amount = !isNaN(rawAmount) && rawAmount > 0 ? Math.round(rawAmount) : 50;

    // Generate unique test voucher hash
    const randomHex = Math.random().toString(36).substring(2, 7) + Date.now().toString(36).slice(-4);
    const voucherCode = `TEST_AP_${amount}_${randomHex}`.toUpperCase();
    const voucherLink = `https://gift.truemoney.com/campaign/?v=${voucherCode}`;
    const id = `test_ap_${Date.now()}_${randomHex}`;

    const row = {
      id,
      code: voucherCode,
      code_type: 'angpao_test',
      credits: amount,
      discount_value: amount,
      discount_type: 'fixed',
      min_spend: 0,
      max_uses: 1,
      used_count: 0,
      used_by: [],
      is_active: true,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };

    const { error: insertErr } = await supabaseAdmin.from('redeem_codes').insert([row]);
    if (insertErr) {
      return NextResponse.json(
        { error: `ไม่สามารถสร้างซองทดสอบได้: ${insertErr.message}` },
        { status: 500 }
      );
    }

    // Record audit log
    recordAuditLog({
      actor: {
        id: authResult.user.id,
        name: authResult.user.email || 'Admin',
        email: authResult.user.email,
        role: 'admin',
      },
      action: 'topup.test_angpao_generated',
      category: 'financial',
      target: {
        id: voucherCode,
        type: 'topup',
        name: `Test Angpao Link (฿${amount})`,
      },
      changes: [
        {
          field: 'amount',
          before: null,
          after: amount,
          label: 'ยอดเงินทดสอบ (บาท)',
        },
      ],
      result: 'success',
      severity: 'low',
      requestId: `req_test_ap_${Date.now()}`,
      reason: 'แอดมินสร้างลิงก์ซองของขวัญ TrueMoney ทดสอบระบบ (ไม่นับเข้า Dashboard)',
    }).catch(() => {});

    return NextResponse.json({
      ok: true,
      voucher: {
        id,
        code: voucherCode,
        link: voucherLink,
        amount,
        maxUses: 1,
        usedCount: 0,
        isUsed: false,
        isActive: true,
        createdAt: row.created_at,
      },
      message: `สร้างลิงก์ซองอั่งเปาทดสอบ ฿${amount} สำเร็จ (ระบบบันทึกสถานะ TEST ไม่นับเข้า Dashboard)`,
    });
  } catch (err: any) {
    console.error('Error in POST /api/admin/angpao/test-gen:', err);
    return NextResponse.json({ error: err.message || 'Internal server error' }, { status: 500 });
  }
}

/**
 * DELETE: Delete one or all test vouchers
 */
export async function DELETE(req: Request) {
  try {
    const authResult = await verifyAdminRequest(req);
    if (!authResult.isAdmin) {
      return NextResponse.json({ error: authResult.error || 'Forbidden' }, { status: 403 });
    }

    const { searchParams } = new URL(req.url);
    const id = searchParams.get('id');
    const action = searchParams.get('action'); // 'all' | 'used'

    if (action === 'all') {
      const { error } = await supabaseAdmin
        .from('redeem_codes')
        .delete()
        .eq('code_type', 'angpao_test');
      if (error) return NextResponse.json({ error: error.message }, { status: 500 });
      return NextResponse.json({ ok: true, message: 'ลบซองทดสอบทั้งหมดเรียบร้อยแล้ว' });
    }

    if (action === 'used') {
      const { error } = await supabaseAdmin
        .from('redeem_codes')
        .delete()
        .eq('code_type', 'angpao_test')
        .gt('used_count', 0);
      if (error) return NextResponse.json({ error: error.message }, { status: 500 });
      return NextResponse.json({ ok: true, message: 'ลบซองทดสอบที่ใช้งานแล้วเรียบร้อย' });
    }

    if (!id) {
      return NextResponse.json({ error: 'Missing voucher ID' }, { status: 400 });
    }

    const { error } = await supabaseAdmin
      .from('redeem_codes')
      .delete()
      .eq('id', id)
      .eq('code_type', 'angpao_test');

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ ok: true, message: 'ลบซองทดสอบเรียบร้อยแล้ว' });
  } catch (err: any) {
    console.error('Error in DELETE /api/admin/angpao/test-gen:', err);
    return NextResponse.json({ error: err.message || 'Internal server error' }, { status: 500 });
  }
}
